begin;
\i packages/db/fixtures/domain.sql
select plan(31);
select ok((select relrowsecurity from pg_class where oid='app_private.auth_social_identities'::regclass),'Identidades OAuth RLS deny by default');
select ok((select relrowsecurity from pg_class where oid='app_private.auth_oauth_transactions'::regclass),'Transacciones OAuth RLS deny by default');
select ok(not has_table_privilege('asisteam_member','app_private.auth_social_identities','SELECT'),'Cliente no lee identidades');
select ok(not has_table_privilege('asisteam_api','app_private.auth_social_identities','SELECT'),'API no lee identidades directamente');
select ok(not has_table_privilege('asisteam_auth','app_private.auth_social_identities','SELECT'),'Auth no lee identidades directamente');
select ok(not has_table_privilege('asisteam_auth','app_private.auth_oauth_transactions','UPDATE'),'Auth no consume tablas directamente');
select ok(not pg_temp.can_execute('asisteam_auth','app_private.password_auth_operation(text,jsonb)','EXECUTE'),'Auth no elude dispatcher');
select ok(not pg_temp.can_execute('asisteam_member','app_private.auth_operation(text,jsonb)','EXECUTE'),'Cliente no vincula identidades');
select ok(not pg_temp.can_execute('asisteam_auth','app_private.import_social_identities()','EXECUTE'),'Runtime no importa vínculos administrativos');
select ok(pg_temp.can_execute('asisteam_auth','app_private.auth_operation(text,jsonb)','EXECUTE'),'Auth usa frontera privada');
insert into app_private.auth_subjects(id,email) values('16300000-0000-4000-8000-000000000001','sql163-owner@example.test');
insert into public.users(id,auth_user_id,email,full_name,birthdate,account_status)
 values('16300000-0000-4000-8000-000000000011','16300000-0000-4000-8000-000000000001','sql163-owner@example.test','Owner sintético','1990-01-01','ACTIVE');
insert into app_private.auth_families(id,subject_id) values('16300000-0000-4000-8000-000000000021','16300000-0000-4000-8000-000000000001');
insert into app_private.auth_social_identities(provider,provider_subject,subject_id) values('google','sql163-imported','16300000-0000-4000-8000-000000000001');
create function app_private.test163_begin(id uuid,link jsonb default null) returns jsonb language sql as $$
 select app_private.auth_operation('oauth_begin',jsonb_build_object('transaction_id',id,'link',link));
$$;
create function app_private.test163_complete(id uuid,sub text,email text,link jsonb default null) returns jsonb language sql as $$
 select app_private.auth_operation('oauth_complete',jsonb_build_object('transaction_id',id,'provider','google','provider_subject',sub,'email',email,'name','Social sintético','subject_id',gen_random_uuid(),'refresh_hash',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'),'link',link));
$$;
select is(app_private.test163_begin('16300000-0000-4000-8000-000000000031'), '{}'::jsonb,'Inicio público sin perfil');
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000031','sql163-imported','different@example.test')->>'subject_id','16300000-0000-4000-8000-000000000001','Proveedor/sub conserva sujeto aunque cambie email');
select is((select id::text from public.users where auth_user_id='16300000-0000-4000-8000-000000000001'),'16300000-0000-4000-8000-000000000011','Conserva public.users.id');
select is((select email from public.users where id='16300000-0000-4000-8000-000000000011'),'sql163-owner@example.test','Login no actualiza email del perfil');
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000031','sql163-imported','different@example.test')->>'error','authentication_required','Reutilización rechazada');
select app_private.test163_begin('16300000-0000-4000-8000-000000000032');
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000032','sql163-unlinked','sql163-owner@example.test')->>'error','authentication_required','Email igual no fusiona ni autentica');
select is((select count(*)::int from app_private.auth_social_identities where provider_subject='sql163-unlinked'),0,'Colisión no crea vínculo');
select ok((select consumed_at is not null from app_private.auth_oauth_transactions where id='16300000-0000-4000-8000-000000000032'),'Colisión consume transacción');
select app_private.test163_begin('16300000-0000-4000-8000-000000000033');
select ok(not (app_private.test163_complete('16300000-0000-4000-8000-000000000033','sql163-new','sql163-new@privaterelay.appleid.com') ? 'error'),'Cuenta nueva única');
select is((select count(*)::int from public.users where email='sql163-new@privaterelay.appleid.com'),1,'Solo un perfil nuevo');
select is((select birthdate from public.users where email='sql163-new@privaterelay.appleid.com'),null::date,'Sin fecha inferida');
select is((select count(*)::int from public.account_consents c join public.users u on u.id=c.user_id where u.email='sql163-new@privaterelay.appleid.com'),0,'Sin consentimiento inferido');
select is((select count(*)::int from public.memberships m join public.users u on u.id=m.user_id where u.email='sql163-new@privaterelay.appleid.com'),0,'Sin membresía inferida');
select is(app_private.test163_begin('16300000-0000-4000-8000-000000000034','{"subject_id":"16300000-0000-4000-8000-000000000001","session_id":"16300000-0000-4000-8000-000000000099"}')->>'error','authentication_required','Link sin familia vigente rechazado');
select is(app_private.test163_begin('16300000-0000-4000-8000-000000000034','{"subject_id":"16300000-0000-4000-8000-000000000001","session_id":"16300000-0000-4000-8000-000000000021"}'),'{}'::jsonb,'Link autorizado por familia vigente');
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000034','sql163-linked','different@example.test')->>'error','authentication_required','Link exige sujeto/familia vinculados a transacción');
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000034','sql163-linked','different@example.test','{"subject_id":"16300000-0000-4000-8000-000000000001","session_id":"16300000-0000-4000-8000-000000000021"}')->>'subject_id','16300000-0000-4000-8000-000000000001','Link explícito conserva sujeto');
select app_private.test163_begin('16300000-0000-4000-8000-000000000035','{"subject_id":"16300000-0000-4000-8000-000000000001","session_id":"16300000-0000-4000-8000-000000000021"}');
update app_private.auth_families set revoked_at=now() where id='16300000-0000-4000-8000-000000000021';
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000035','sql163-revoked','different@example.test','{"subject_id":"16300000-0000-4000-8000-000000000001","session_id":"16300000-0000-4000-8000-000000000021"}')->>'error','authentication_required','Revocación durante proveedor invalida linking');
select app_private.test163_begin('16300000-0000-4000-8000-000000000036');
update app_private.auth_oauth_transactions set expires_at=now()-interval '1 second' where id='16300000-0000-4000-8000-000000000036';
select is(app_private.test163_complete('16300000-0000-4000-8000-000000000036','sql163-expired','expired@example.test')->>'error','authentication_required','Transacción vencida rechazada');
select is((select count(*)::int from app_private.auth_social_identities where provider_subject in ('sql163-revoked','sql163-expired')),0,'Denegación no crea vínculos');
select is((select count(*)::int from app_private.auth_credentials c join public.users u on u.auth_user_id=c.subject_id where u.email='sql163-new@privaterelay.appleid.com'),0,'OAuth no genera contraseña');
select * from finish();
rollback;
